public void buf2BufByName(Common  _from, Common  _to)
{
    DictTable   dictTableFrom   = new DictTable(_from.TableId);
    DictTable   dictTableTo     = new DictTable(_to.TableId);
    DictField   dictFieldFrom;
    FieldId     fieldIdFrom     = dictTableFrom.fieldNext(0);
    FieldId     fieldIdTo;

    while (fieldIdFrom && !isSysId(fieldIdFrom))
    {
        dictFieldFrom = new DictField(_from.TableId, fieldIdFrom);

        if(dictFieldFrom)
        {
            fieldIdTo = dictTableTo.fieldName2Id(dictFieldFrom.name());
            if(fieldIdTo)
            _to.(fieldIdTo) = _from.(fieldIdFrom);
        }
        fieldIdFrom = dictTableFrom.fieldNext(fieldIdFrom);
    }
}

public void process(METTierRateCalculationContract _contract)
{
    TAMRebateTrans          rebateTrans;
    TAMRebateDeal           rebateDeal;
    TAMRebateTable          rebateTable;
    TAMRebateLine           rebateLine;
    TAMRebateDateTrans      rebateDateTrans;
    METTierRebateTrans      tierRebateTrans;
    real                    weeks;
    METTierRateTrans        tierRateTrans;
    TAMRebateDate           rebateDate;
    CustInvoiceTrans        custInvoiceTrans;
    CustTable               custTable;
    InventTable             inventTable;
    CustInvoiceJour         custInvoiceJour;

    //weeks = (_contract.parmToDate() - _contract.parmFromDate())/7;

    //delete_from tierRateTransCalc;

    FiscalCalendarPeriod fiscalCalendarPeriod;
    FiscalCalendar fiscalCal;// = FiscalCalendar::find(Ledger::fiscalCalendar(CompanyInfo::current()));
    FiscalCalendarYear  fiscalCalYear;

    select firstonly fiscalCalendarPeriod join fiscalCalYear
            where fiscalCalendarPeriod.FiscalCalendarYear == fiscalCalYear.RecId
            join fiscalCal
            where fiscalCal.RecId == fiscalCalYear.FiscalCalendar
            && fiscalCal.CalendarId == "Cal_Year"
            && fiscalCalendarPeriod.Type == FiscalPeriodType::Operating
            && fiscalCalendarPeriod.StartDate == _contract.parmFromDate()
            && fiscalCalendarPeriod.EndDate == _contract.parmToDate();

    int weekPeriod = 0;
    int calendarMonth = 0;
    if (fiscalCalendarPeriod.METNoOfWeeksForPeriod == METNoOfWeeksForPeriod::Five)
    {
        calendarMonth = 5;
    }
    else if (fiscalCalendarPeriod.METNoOfWeeksForPeriod == METNoOfWeeksForPeriod::Four)
    {
        calendarMonth = 4;
    }
    else if(fiscalCalendarPeriod.METNoOfWeeksForPeriod == METNoOfWeeksForPeriod::Empty)
    {
      throw error("Please set No of weeks for the period in the fiscal calendar");
    }

    select firstonly rebateDeal
        where rebateDeal.Deal == _contract.parmRebateDealRecId();

    while select rebateTable
    where rebateTable.METTierLineType == METTierLineType::Rate
    && rebateTable.RebateDeal == rebateDeal.RecId
    {
        int i = 2;
        select firstonly custTable
            where custTable.AccountNum == rebateTable.AccountRelation
            && custTable.DataAreaId == rebateTable.RebateCompanyId
            && rebateTable.ModuleInventCustVend == ModuleInventCustVend::Cust
            && rebateTable.AccountCode == TableGroupAll::Table;

        select firstonly inventTable
            where inventTable.ItemId == rebateTable.ItemRelation
            && inventTable.DataAreaId == rebateTable.RebateCompanyId
            && rebateTable.ItemCode == TableGroupAll::Table;

        //if (custTable.RecId && inventTable.RecId)
        {
            while select custInvoiceTrans join custInvoiceJour
                where custInvoiceJour.SalesId == custInvoiceTrans.SalesId
                && custInvoiceJour.InvoiceId == custInvoiceTrans.InvoiceId
                && custInvoiceJour.InvoiceDate == custInvoiceTrans.InvoiceDate
                && custInvoiceJour.numberSequenceGroup == custInvoiceTrans.numberSequenceGroup
                //&& custInvoiceTrans.ItemId == inventTable.ItemId
                && custInvoiceTrans.InvoiceDate >= _contract.parmFromDate()
                && custInvoiceTrans.InvoiceDate <= _contract.parmToDate()
                //&& custInvoiceJour.OrderAccount == custTable.AccountNum
            {
                i=2;
                while (i>0)
                {

                    tierRebateTrans.clear();
                    tierRebateTrans.Claimed = NoYes::No;
                    tierRebateTrans.CurrencyCode = custInvoiceTrans.CurrencyCode;
                    tierRebateTrans.DefaultDimension = custInvoiceTrans.DefaultDimension;
                    tierRebateTrans.InventDimId = rebateTable.InventDimId;
                    tierRebateTrans.ExcludeRebateManagement = NoYes::No;
                    tierRebateTrans.ItemId = custInvoiceTrans.ItemId;
                    //tierRebateTrans.METTierRateTransRecID = tierRateTrans.RecId;
                    tierRebateTrans.PostingAmount = custInvoiceTrans.LineAmount;
                    //tierRebateTrans.ProvisionAmount
                    tierRebateTrans.RefCompanyId = custInvoiceTrans.DataAreaId;
                    tierRebateTrans.RefRecId = custInvoiceTrans.RecId;
                    tierRebateTrans.RefTableId = custInvoiceTrans.TableId;
                    //tierRebateTrans.RefUnitId = custInvoiceTrans.
                    tierRebateTrans.RebateAmount  = custInvoiceTrans.LineAmount;
                    tierRebateTrans.RebateFromDate = _contract.parmFromDate();
                    tierRebateTrans.RebateToDate = _contract.parmToDate();
                    tierRebateTrans.RebateId = rebateTable.RebateId;
                    tierRebateTrans.RebateQty = custInvoiceTrans.Qty;
                    tierRebateTrans.RebateRefAccount = custInvoiceJour.OrderAccount;
                    tierRebateTrans.RebateRefAmount = custInvoiceTrans.LineAmount;
                    tierRebateTrans.RebateRefDate = custInvoiceTrans.InvoiceDate;
                    tierRebateTrans.RebateRefQty = custInvoiceTrans.Qty;
                    tierRebateTrans.RebateRefId = custInvoiceJour.SalesId;
                    //tierRebateTrans.RebateTransId = rebateTable.
                    tierRebateTrans.RebateRefSoldToAccount = custInvoiceJour.OrderAccount;
                    tierRebateTrans.TAMRebateDealId = rebateTable.TAMRebateDeal().Deal;
                    if (i==1)
                    {
                        tierRebateTrans.RebateTransactionType = TAMRebateTransactionType::Provision;
                        i--;
                    }
                    else if (i==2)
                    {
                        tierRebateTrans.RebateTransactionType = TAMRebateTransactionType::Rebate;
                        i--;
                    }
                    tierRebateTrans.insert();
                }
            }   

            select firstonly rebateDate
                where rebateDate.RebateId == rebateTable.RebateId;            

            TransDate   fromDate = _contract.parmFromDate();                    

            if(rebateDate.RebateFromDate >= _contract.parmFromDate() && _contract.parmToDate() <= rebateDate.RebateToDate)
            {
                tierRateTrans.clear();
                tierRateTrans.FromDate = _contract.parmFromDate();
                tierRateTrans.ToDate = _contract.parmToDate();
                tierRateTrans.TAMRebateDealId = rebateDeal.Deal;
                tierRateTrans.RebateTransactionType = TAMRebateTransactionType::Rebate;
                tierRateTrans.RebateId = rebateTable.RebateId;
                tierRateTrans.insert();

                update_recordSet tierRebateTrans
                setting METTierRateTransRecID = tierRateTrans.RecId
                where tierRebateTrans.RebateRefDate >= tierRateTrans.FromDate
                && tierRebateTrans.RebateRefDate <= tierRateTrans.ToDate
                && tierRebateTrans.RebateId == rebateTable.RebateId
                && tierRebateTrans.TAMRebateDealId == tierRateTrans.TAMRebateDealId
                    && tierRebateTrans.RebateTransactionType == TAMRebateTransactionType::Rebate;

                select sum(RebateRefAmount) from tierRebateTrans
                        where tierRebateTrans.METTierRateTransRecID == tierRateTrans.RecId
                    && tierRebateTrans.RebateTransactionType == TAMRebateTransactionType::Rebate;
                ttsbegin;
                tierRateTrans.selectForUpdate(true);
                tierRateTrans.AgEligibleTransAmount = tierRebateTrans.RebateRefAmount;
                tierRateTrans.WeeklyAverage = tierRateTrans.AgEligibleTransAmount/calendarMonth;

                select firstonly rebateLine
                    where rebateLine.RebateFrom <= tierRateTrans.AgEligibleTransAmount
                    && rebateLine.RebateLimit >= tierRateTrans.AgEligibleTransAmount
                    && rebateLine.RebateId == rebateTable.RebateId;
                tierRateTrans.EligibleRebate = rebateLine.RebateAmount;
                tierRateTrans.doUpdate();
                ttscommit;

                while (calendarMonth > weekPeriod)
                {
                    weekPeriod++;
                    tierRateTrans.clear();
                    tierRateTrans.FromDate = fromDate;
                    tierRateTrans.ToDate = tierRateTrans.FromDate + 6;//this.getRebateToDate(_rebateDate, _scanSupplierTransDate);//_contract.parmToDate()
                    tierRateTrans.TAMRebateDealId = rebateDeal.Deal;
                    tierRateTrans.RebateTransactionType = TAMRebateTransactionType::Provision;
                    tierRateTrans.RebateId = rebateTable.RebateId;
                    tierRateTrans.insert();

                    update_recordSet tierRebateTrans
                    setting METTierRateTransRecID = tierRateTrans.RecId
                    where tierRebateTrans.RebateRefDate >= tierRateTrans.FromDate
                    && tierRebateTrans.RebateRefDate <= tierRateTrans.ToDate
                    && tierRebateTrans.RebateId == rebateTable.RebateId
                    && tierRebateTrans.TAMRebateDealId == tierRateTrans.TAMRebateDealId
                    && tierRebateTrans.RebateTransactionType == TAMRebateTransactionType::Provision;

                    select sum(RebateRefAmount) from tierRebateTrans
                        where tierRebateTrans.METTierRateTransRecID == tierRateTrans.RecId;
                    ttsbegin;
                    tierRateTrans.selectForUpdate(true);
                    tierRateTrans.AgEligibleTransAmount = tierRebateTrans.RebateRefAmount;                        

                    select firstonly rebateLine
                    where rebateLine.RebateFrom <= tierRateTrans.AgEligibleTransAmount
                    && rebateLine.RebateLimit >= tierRateTrans.AgEligibleTransAmount
                    && rebateLine.RebateId == rebateTable.RebateId;

                    tierRateTrans.EligibleRebate = rebateLine.RebateAmount;
                    tierRateTrans.doUpdate();
                    ttscommit;

                    fromDate = tierRateTrans.ToDate+1;
                }                        
            }
        }            
    }
    /*while select rebateTrans join rebateDateTrans
        where rebateTrans.RebateTransId == rebateDateTrans.RebateTransId
        && rebateTrans.RebateRefDate >= _contract.parmFromDate()
        && rebateTrans.RebateRefDate <= _contract.parmToDate()
        join rebateTable
        where rebateTable.RebateId == rebateDateTrans.RebateId
        join rebateDeal
        where rebateDeal.RecId == rebateTable.RebateDeal
        && rebateDeal.Deal == _contract.parmRebateDealRecId()
    {
        tierRateTransCalc.clear();
        tierRateTransCalc.FromDate = _contract.parmFromDate();
        tierRateTransCalc.ToDate = _contract.parmToDate();
        tierRateTransCalc.AgEligibleTransAmount = rebateTrans.RebateRefAmount;
        tierRateTransCalc.TAMRebateDealId = rebateDeal.Deal;
        tierRateTransCalc.ItemId = rebateTrans.ItemId;
        tierRateTransCalc.RebateId = rebateTable.RebateId;
        tierRateTransCalc.RebateRefAccount = rebateTrans.RebateRefAccount;
        tierRateTransCalc.RebateTransactionType = rebateDateTrans.RebateTransactionType;
        tierRateTransCalc.insert();

        if (tierRateTransCalc.RecId)
        {
            this.buf2BufByName(rebateTrans,tierRebateTrans);
            tierRebateTrans.insert();
        }
    }*/

    /*while select sum(AgEligibleTransAmount) from tierRateTransCalc
        group by tierRateTransCalc.ItemId, tierRateTransCalc.RebateId,tierRateTransCalc.RebateRefAccount,
        tierRateTransCalc.RebateTransactionType, tierRateTransCalc.TAMRebateDealId
    {
        tierRateTrans.clear();
        tierRateTrans.FromDate = _contract.parmFromDate();
        tierRateTrans.ToDate = _contract.parmToDate();
        tierRateTrans.AgEligibleTransAmount = tierRateTransCalc.AgEligibleTransAmount;
        tierRateTrans.WeeklyAverage = tierRateTransCalc.AgEligibleTransAmount/weeks;
        tierRateTrans.TAMRebateDealId = tierRateTransCalc.TAMRebateDealId;

        select firstonly rebateLine
            where rebateLine.RebateFrom <= tierRateTransCalc.AgEligibleTransAmount
            && rebateLine.RebateLimit >= tierRateTransCalc.AgEligibleTransAmount
            && rebateLine.RebateId == tierRateTransCalc.RebateId;

        tierRateTrans.EligibleRebate = rebateLine.RebateAmount;
        tierRateTrans.RebateTransactionType = tierRateTransCalc.RebateTransactionType;
        tierRateTrans.insert();

        if (tierRateTrans.RecId)
        {
            update_recordSet tierRebateTrans
            setting METTierRateTransRecID = tierRateTrans.RecId
            where tierRebateTrans.ItemId == tierRateTransCalc.ItemId
            && tierRebateTrans.RebateId == tierRateTransCalc.RebateId
            && tierRebateTrans.RebateRefAccount == tierRateTransCalc.RebateRefAccount
            && tierRebateTrans.RebateTransactionType == tierRateTransCalc.RebateTransactionType;
            //&& tierRebateTrans.TAMRebateDealId == tierRateTransCalc.TAMRebateDealId;
        }
    }*/
}

protected Days getRebateToDate(TAMRebateDate  _rebateDate, TransDate  _scanSupplierTransDate)
{
    switch(_rebateDate.RebatePeriodCode)
    {
        case TAMRebatePeriodCode::Month:
            return dayOfMth(dateEndMth(_scanSupplierTransDate)) * _rebateDate.RebatePer;
        case TAMRebatePeriodCode::Week:
            return  METConstants::weekDays * _rebateDate.RebatePer;
        case TAMRebatePeriodCode::Year:
            xSession xSession = new xSession();
            return dayOfYr(DateTimeUtil::getEndOfYearDate(xSession.preferredLocale(), _scanSupplierTransDate)) * _rebateDate.RebatePer;
        case TAMRebatePeriodCode::Day:
        default:
            return METConstants::oneDay * _rebateDate.RebatePer;
    }
}
